// Get the LinkedIn URL from the previous node
const linkedinUrl = $input.first().json.linkedin_url;

if (!linkedinUrl) {
  return [{ error: 'No LinkedIn URL provided' }];
}

try {
  // Normalize URL
  let url = linkedinUrl.trim()
    .replace(/^https?:\/\//, '')  // remove http:// or https://
    .replace(/^www\./, '');       // remove www.

  // Extract the profile path (in /in/ or /pub/)
  const match = url.match(/linkedin\.com\/(in|pub)\/([^/?#]+)/i);

  if (!match) {
    return [{ error: 'Invalid LinkedIn profile URL', original: linkedinUrl }];
  }

  let publicIdentifier = match[2];

  // Remove trailing slash if present
  publicIdentifier = publicIdentifier.replace(/\/$/, '');

  return [{
    original_url: linkedinUrl,
    public_identifier: publicIdentifier
  }];

} catch (error) {
  return [{
    error: 'Failed to parse LinkedIn URL',
    details: error.message,
    original: linkedinUrl
  }];
}

// Step 0: get the first item
const item = $input.first().json;

// Step 1: get the error message string
const errorMessage = item.error?.message || null;

let detail = null;

if (errorMessage) {
  try {
    // Step 2: remove the leading "422 - " (status code)
    const jsonStringEscaped = errorMessage.replace(/^\d+\s*-\s*/, '');

    // Step 3: parse the outer string to unescape it
    // converts "\"{...}\"" into "{...}"
    const jsonString = JSON.parse(jsonStringEscaped);

    // Step 4: parse the inner JSON
    const parsedError = JSON.parse(jsonString);

    // Step 5: extract the detail
    detail = parsedError.detail || null;

  } catch (e) {
    detail = null;
  }
}

return [
  {
    json: {
      error_detail: detail
    }
  }
];

// range in seconds
const minSeconds = 90;  // 1 min 30 sec
const maxSeconds = 180; // 3 min

// random seconds between min and max
const randomSeconds =
  Math.floor(Math.random() * (maxSeconds - minSeconds + 1)) + minSeconds;

// convert to minutes (decimal)
const randomMinutes = randomSeconds / 60;

return [
  {
    json: {
      delay_seconds: randomSeconds,
      delay_minutes: randomMinutes,
    }
  }
];

const now = new Date();

// -------------------
// Define working hours
// -------------------
const startHour = 8;  // 8 AM
const endHour = 17;   // 5 PM

const dayOfWeek = now.getDay(); // 0 = Sunday, 1 = Monday ... 6 = Saturday

// -------------------
// Check if now is within working hours (Monday–Friday 8AM–5PM)
// -------------------
const startToday = new Date(now);
startToday.setHours(startHour, 0, 0, 0);

const endToday = new Date(now);
endToday.setHours(endHour, 0, 0, 0);

const isWeekday = dayOfWeek >= 1 && dayOfWeek <= 5;
const isBetweenWorkingHours = isWeekday && now >= startToday && now <= endToday;

// -------------------
// Calculate next working 8AM
// -------------------
let nextWorking8AM = new Date(now);

if (dayOfWeek >= 1 && dayOfWeek <= 4) {
  // Monday–Thursday
  if (now < startToday) {
    nextWorking8AM = startToday; // today 8AM
  } else {
    nextWorking8AM.setDate(nextWorking8AM.getDate() + 1);
    nextWorking8AM.setHours(startHour, 0, 0, 0);
  }
} else if (dayOfWeek === 5) {
  // Friday
  if (now < startToday) {
    nextWorking8AM = startToday; // Friday 8AM
  } else {
    nextWorking8AM.setDate(nextWorking8AM.getDate() + 3); // Monday
    nextWorking8AM.setHours(startHour, 0, 0, 0);
  }
} else if (dayOfWeek === 6) {
  // Saturday → next Monday
  nextWorking8AM.setDate(nextWorking8AM.getDate() + 2);
  nextWorking8AM.setHours(startHour, 0, 0, 0);
} else if (dayOfWeek === 0) {
  // Sunday → next Monday
  nextWorking8AM.setDate(nextWorking8AM.getDate() + 1);
  nextWorking8AM.setHours(startHour, 0, 0, 0);
}

// -------------------
// Hours until next working 8AM
// -------------------
const hoursUntilNextWorking8AM = (nextWorking8AM - now) / (1000 * 60 * 60);

return [
  {
    json: {
      now: now.toISOString(),
      dayOfWeek,
      isWeekday,
      isBetweenWorkingHours,
      nextWorking8AM: nextWorking8AM.toISOString(),
      hoursUntilNextWorking8AM: Number(hoursUntilNextWorking8AM.toFixed(2))
    }
  }
];

const canaux = $input.first().json.Channel[0].value;

// Force into array
const channelsArray = Array.isArray(canaux)
  ? canaux
  : [canaux];

// Check if LinkedIn exists
const hasLinkedin = channelsArray.some(
  item => item.toLowerCase() === "linkedin"
);

return [
  {
    json: {
      hasLinkedin
    }
  }
];

